function el(tag, attrs = {}, ...children) {
  const n = document.createElement(tag);
  for(const [key,value] of Object.entries(attrs)) {
    if(key.startsWith('on'))n.addEventListener(key.slice(2).toLowerCase(),value);
    else if(key === 'class')n.className=value;
    else if(key === 'text')n.textContent=value;
    else if(key in n)n[key]=value;
    else n.setAttribute(key,value);
  }
  for(const child of children.flat())if(child !== undefined && child !== null)n.append(child instanceof Node ? child : document.createTextNode(String(child)));
  return n;
}
