async function refresh() {
  if(loading)return;loading=true;$('refresh').disabled=true;$('page-notice').replaceChildren();
  $('content').replaceChildren(el('div',{class:'loading'},'Читаем настройки роутера…'));
  try {
    const group=current;const data=await api('read?group='+group);
    if(group!==current)return;cached=data;$('content').replaceChildren(await renderers[group](data));
    $('updated').textContent='Обновлено '+new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'});
    if(!info.writeSupported)$('page-notice').append(note('Для этой версии прошивки доступно чтение. Сохранение параметров проверено для 1.1.123.',true));
    if(info.demo)$('page-notice').append(note('Демонстрационный роутер. Данные вымышлены, изменения не отправляются на реальное устройство.'));
    const failed=Object.entries(data).filter(([,v])=>!ok(v));
    if(failed.length)$('page-notice').append(note('Часть параметров недоступна. Доступные настройки показаны ниже.',true));
    $('page-notice').append(note('Чтение проверено на RD08 1.1.123. Новые операции записи сверены с прошивкой; применение на оборудовании не проверялось.'));
  }catch(e){$('content').replaceChildren(el('div',{class:'inline-error',role:'alert'},e.message));}
  finally{loading=false;$('refresh').disabled=false;}
}
