function parentalAppForms(userId,apps,allow){
  return el('div',{},ok(allow)&&String(cached.features?.apps?.mipctlv2_temp_allow)==='1'?formCard('Временное разрешение','Действует до следующего периода расписания.',[fields('on','Разрешение включено',allow.allow,'checkbox',[],{full:true})],'parentalAllow',x=>({...x,user_id:userId})):null,...(apps?.list||[]).map(category=>{
    const specs=[fields('on','Ограничивать категорию',category.enable===true?1:category.enable,'checkbox',[],{full:true})];
    if(Number.isInteger(+category.time_quota)&&+category.time_quota>=0)specs.push(fields('quotaMinutes','Квота, минут в сутки',category.time_quota,'number',[],{min:0,max:1440,required:true,hint:'0 — полностью запретить включённую категорию.'}));
    for(const[i,a]of (category.app_list||[]).entries())specs.push(fields('app'+i,a.name,a.enable===true?1:a.enable,'checkbox',[],{full:true}));
    return details(category.class_name,formCard(category.class_name,'Изменяются только эта категория и перечисленные приложения.',specs,'parentalApps',x=>({user_id:userId,class_name:category.class_name,on:x.on,...(x.quotaMinutes?{quotaMinutes:x.quotaMinutes}:{}),apps:(category.app_list||[]).map((a,i)=>({name:a.name,on:x['app'+i]}))})));
  }));
}
