$('login-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button[type=submit]');button.disabled=true;$('login-error').textContent='';try{const password=$('password').value;await api('login',{password});$('password').value='';info=await api('info');showShell();await navigate(location.hash.slice(1)||'overview');}catch(e){$('login-error').textContent=e.message;}finally{button.disabled=false;}});
