const dialog=$('confirm-dialog');
const close=()=>{if($('confirm-apply').disabled)return;dialog.close();pending=null;previousFocus?.focus();};
$('close-dialog').addEventListener('click',close);$('cancel-apply').addEventListener('click',close);
dialog.addEventListener('cancel',event=>{if($('confirm-apply').disabled)event.preventDefault();else{pending=null;previousFocus?.focus();}});
$('confirm-apply').addEventListener('click',async()=>{
  if(!pending){close();return;}const button=$('confirm-apply');button.disabled=true;button.textContent='Сохраняем…';$('apply-error').textContent='';
  const appliedGroup=current;
  try{const result=await api('apply',{ticket:pending.ticket});pending=null;dialog.close();toast(result.message||(result.wait?`Настройка принята. Повторное чтение через ${result.wait} с.`:'Настройка сохранена.'));if(result.reauth){showLogin();$('password').focus();return;}if(result.wait)setTimeout(()=>{if(current===appliedGroup&&info.authenticated)refresh();},result.wait*1000);else await refresh();}
  catch(e){$('apply-error').textContent=e.message;button.textContent='Закрыть';pending=null;button.disabled=false;}
  finally{if(pending||!dialog.open){button.disabled=false;button.textContent='Применить';}}
});
